// Jenkins pipeline for Gkeyll, built/run on our own persistent machines
// (see ci/jenkins/README.md for how the Jenkins job driving this is set up).
//
// Unlike a shared, long-lived gkylsoft/, each build clones the repo fresh
// and builds its own dependencies from scratch into its own workspace
// (mirroring .github/workflows/mac_build.yml), then actually runs the unit
// tests rather than just building them.
//
// Scripted (not declarative) pipeline, since we run the same steps in
// parallel across a set of named nodes that will grow over time and may mix
// operating systems (hence the per-node mkdeps/configure script choice).

def buildAndTest(String mkdepsScript, String configureScript) {
    stage('Environment') {
        sh 'printenv'
    }
    stage('Clean') {
        // The workspace (and its build/ and gkylsoft/ dirs) persists across
        // builds for a given branch/PR, so a build interrupted or racing
        // mid-compile can leave stale/corrupted files behind that a later
        // incremental step wrongly treats as up to date (e.g. missing
        // symbols at link time, without ever recompiling/reinstalling).
        // Wipe both every run so each build is truly from scratch: the
        // install-deps scripts already re-download/rebuild everything
        // unconditionally, but don't clear their install prefix first, so a
        // stale gkylsoft/ could otherwise mix old and new files.
        sh 'make clean'
        sh 'rm -rf "$WORKSPACE/gkylsoft"'
        // Side workspace used to build a same-session `main` baseline for
        // the regression-diff stage below (PR builds only).
        sh 'rm -rf "$WORKSPACE/_main_baseline"'
    }
    stage('Dependencies') {
        // Build gkylsoft/ from scratch inside this build's own workspace
        // (rather than a shared, fixed path) so that concurrent builds for
        // different branches/PRs on the same node never share or clobber
        // each other's dependency trees.
        sh "PREFIX=\"\$WORKSPACE/gkylsoft\" ./machines/${mkdepsScript}"
    }
    stage('Configure') {
        sh "PREFIX=\"\$WORKSPACE/gkylsoft\" ./machines/${configureScript}"
    }
    stage('Unit tests') {
        sh 'make -j3 check'
    }
    stage('Regression build') {
        sh 'make -j3 regression'
    }
    stage('Install') {
        // Needed by 'gkeyll runregression': it compiles C regression tests
        // on the fly using the installed share/Makefile, and 'gkeyll' itself
        // is the interpreter runregression runs as.
        //
        // Use 'install' (from the generated alltargets.mak), not
        // 'gkeyll-install' (defined directly in the top-level Makefile):
        // the latter has two independent prerequisite chains that both
        // rebuild the same build/**/libg0*.so files, which can race under
        // -j and fail with e.g. "cp: .../libg0vlasov.so: No such file or
        // directory" when nothing has pre-built them yet.
        sh 'make -j3 install'
    }

    if (env.CHANGE_ID) {
        // Only PR builds run the regression-diff stages below: they compare
        // against a baseline built from the PR's target branch, which is
        // meaningless for a build *of* that branch itself.
        def regressionJobs = ''
        stage('Set regression concurrency') {
            regressionJobs = sh(returnStdout: true, script: '''#!/bin/bash
                set -euo pipefail

                physical_cores=''
                if command -v sysctl >/dev/null 2>&1; then
                    physical_cores="$(sysctl -n hw.physicalcpu 2>/dev/null || true)"
                fi
                if [[ ! "$physical_cores" =~ ^[1-9][0-9]*$ ]] && command -v nproc >/dev/null 2>&1; then
                    physical_cores="$(nproc 2>/dev/null || true)"
                fi
                if [[ ! "$physical_cores" =~ ^[1-9][0-9]*$ ]]; then
                    physical_cores=1
                    echo 'Could not detect physical CPU cores; using one regression job.' >&2
                fi

                regression_jobs=$((physical_cores / 2))
                if (( regression_jobs < 1 )); then
                    regression_jobs=1
                fi
                echo "Detected $physical_cores physical CPU core(s); using $regression_jobs concurrent regression job(s)." >&2
                printf '%s\n' "$regression_jobs"
            ''').trim()
        }
        stage('Regression baseline (main)') {
            buildRegressionBaseline(
                mkdepsScript,
                configureScript,
                env.CHANGE_TARGET ?: 'main',
                regressionJobs
            )
        }
        stage('C regression tests') {
            def gkeyll = "\$WORKSPACE/gkylsoft/gkeyll/bin/gkeyll"
            def resultsDir = "\$WORKSPACE/gkylsoft/gkeyll-results"
            def baselineResultsDir = "\$WORKSPACE/_main_baseline/gkylsoft/gkeyll-results"
            sh "\"${gkeyll}\" runregression configure --source-dir \"\$WORKSPACE\" --prefix \"\$WORKSPACE/gkylsoft\""
            // Move (not copy) the main-branch baseline's accepted outputs
            // into the PR's own results tree: _main_baseline is scratch
            // space nothing else reads afterward and gets wiped by the next
            // build's Clean stage anyway, so moving avoids briefly doubling
            // disk usage on what can be a large number of regression files.
            def moveCmd = "set -e\n"
            // Move the C accepted outputs for every regression-test layer.
            def REGRESSION_LAYERS = ['moments', 'vlasov', 'gyrokinetic', 'pkpm']
            for (layer in REGRESSION_LAYERS) {
                moveCmd += "if [ -d \"${baselineResultsDir}/${layer}/creg-accepted\" ]; then rm -rf \"${resultsDir}/${layer}/creg-accepted\"; mv \"${baselineResultsDir}/${layer}/creg-accepted\" \"${resultsDir}/${layer}/creg-accepted\"; fi\n"
            }
            sh moveCmd
            sh "\"${gkeyll}\" runregression run --c-only check --timeout 900 --jobs ${regressionJobs}"
            sh "\"${gkeyll}\" \"\$WORKSPACE/ci/jenkins/check_regression_results.lua\" \"${resultsDir}\" \"\$WORKSPACE/ci/jenkins/expected_regression_diffs.txt\""
        }
    } else {
        // Cheap hygiene check for `main`-branch builds: a leftover
        // acknowledgment entry from a just-merged PR would otherwise
        // silently mask a real future regression on the same test name.
        stage('Check for stale regression acknowledgments') {
            sh '''
                if grep -qE '^[^#[:space:]]' ci/jenkins/expected_regression_diffs.txt 2>/dev/null; then
                    echo "WARNING: ci/jenkins/expected_regression_diffs.txt still has active entries on main -- clear it out now that the PR that added them is merged (see ci/jenkins/README.md)."
                fi
            '''
        }
    }
}

// Builds `baseBranch` (normally the PR's target branch) from scratch in a
// side workspace and runs the complete non-ignored C regression suite's
// 'create' step there,
// producing accepted baselines generated on this exact node/build -- so the
// PR's own C-regression 'check' run (see buildAndTest) has something to diff
// against without relying on a stale or cross-machine-generated baseline.
def buildRegressionBaseline(String mkdepsScript, String configureScript, String baseBranch, String regressionJobs) {
    dir('_main_baseline') {
        // A plain shallow, single-branch clone rather than a GitSCM
        // checkout: the latter defaults to fetching every branch/tag in
        // the whole repo (no refspec given), which timed out after 10
        // minutes enumerating 100k+ objects. We only need this branch's tip.
        sh "git clone --depth 1 --branch ${baseBranch} https://github.com/gkeyllorg/gkeyll ."
        sh "PREFIX=\"\$WORKSPACE/_main_baseline/gkylsoft\" ./machines/${mkdepsScript}"
        sh "PREFIX=\"\$WORKSPACE/_main_baseline/gkylsoft\" ./machines/${configureScript}"
        // See the comment on the 'Install' stage above re: install vs gkeyll-install.
        sh 'make -j3 install'
        def gkeyll = "\$WORKSPACE/_main_baseline/gkylsoft/gkeyll/bin/gkeyll"
        sh "\"${gkeyll}\" runregression configure --source-dir \"\$WORKSPACE/_main_baseline\" --prefix \"\$WORKSPACE/_main_baseline/gkylsoft\""
        sh "\"${gkeyll}\" runregression run --c-only create --timeout 900 --jobs ${regressionJobs}"
    }
}

